<?php require __DIR__.'/app/bootstrap.php'; require __DIR__.'/app/tickets.php'; require __DIR__.'/app/layout.php'; $user=require_permission('create_tickets'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$v=array_map(fn($x)=>trim((string)$x),$_POST);$subs=TICKET_CATEGORIES[$v['category']??'']??null;if(empty($v['issue_escalator'])||empty($v['subject'])||$subs===null||!isset($v['department_id'])||empty($v['employee_name'])||empty($v['description'])||($subs&&(!in_array($v['subcategory']??'', $subs,true))))$error='Complete all required fields with a valid category and subcategory.';else{$pdo=db();$pdo->beginTransaction();try{$number='CNG-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$q=$pdo->prepare('INSERT INTO tickets(ticket_number,issue_escalator,subject,category,subcategory,department_id,employee_name,description,assignee_id,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$number,$v['issue_escalator'],$v['subject'],$v['category'],$v['subcategory']?:null,(int)$v['department_id'],$v['employee_name'],$v['description'],$v['assignee_id']?:(null),$user['id']]);$id=(int)$pdo->lastInsertId();activity($id,$user['id'],'created',['ticket_number'=>$number]);$pdo->commit();redirect('ticket.php?id='.$id);}catch(Throwable $e){$pdo->rollBack();$error='Ticket could not be created.';}}}
$departments=db()->query('SELECT id,name FROM departments ORDER BY name')->fetchAll();$users=active_users();page_start('Create ticket',$user); ?>
<div class="page-head"><div><p class="eyebrow">New record</p><h1>Create ticket</h1></div></div><?php if($error):?><p><?=e($error)?></p><?php endif;?><form method="post" class="ticket-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Issue Escalator<input name="issue_escalator" required></label><label>Subject<input name="subject" required></label><label>Category<select name="category" id="category" required><option value="">Select category</option><?php foreach(TICKET_CATEGORIES as $c=>$s):?><option><?=e($c)?></option><?php endforeach;?></select></label><label>Subcategory<select name="subcategory" id="subcategory"><option value="">Select category first</option></select></label><label>Department<select name="department_id" required><?php foreach($departments as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></label><label>Employee<input name="employee_name" required></label><label>Assignee<select name="assignee_id"><option value="">Unassigned</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['full_name'])?></option><?php endforeach;?></select></label><label>Description<textarea name="description" required rows="6"></textarea></label><button class="button">Create ticket</button></form><script>const map=<?=json_encode(TICKET_CATEGORIES)?>,c=document.querySelector('#category'),s=document.querySelector('#subcategory');c.onchange=()=>{s.innerHTML='<option value="">No subcategory</option>';(map[c.value]||[]).forEach(x=>s.add(new Option(x,x)));s.required=(map[c.value]||[]).length>0};</script><?php page_end();
